import s from"../../../src/component/Base.mjs";export default Neo.setupClass(class extends s{static config={className:"Workstation.view.StatusComponent",cls:["workstation-statusbar"],flex:"none",reference:"status-bar",bind:{html(s){if("planning"===s.dock.perspective.active)return`<span>${this.getStore("people").count} people</span><span>${this.getStore("workItems").count} work items</span><span>${this.getStore("planTasks").count} plan tasks</span>`;const e=this.getStore("feed"),t=this.getStore("scale");return`<span>20 dock items</span><span>${(new Intl.NumberFormat).format(t.count)} scale rows</span><span>${e.count}/${e.maxRecords} feed rows</span><span>${1e3*e.batchSize/e.intervalMs} events/sec</span>`}}}});